  "Broadcast exchange": { definition: "A Spark plan operation that distributes a copy of data to workers, commonly for a broadcast join.", aliases: ["BroadcastExchange"] },
  "Broadcast": { definition: "Distributing a copy of data to workers so each can use it locally, as in Spark broadcast joins or broadcast variables.", aliases: ["broadcasting"] },
