  "Broadcast hash join": { definition: "A join that distributes a small input to workers and probes an in-memory hash table there, avoiding a shuffle of the large input.", aliases: ["broadcast join", "broadcast joins", "broadcast hash", "BroadcastHashJoin"] },
  "Sort-merge join": { definition: "A join that brings matching keys together, sorts inputs as needed, and merges their ordered records. It suits large inputs and can spill during sorting.", aliases: ["sort-merge joins", "sort-merge", "SortMergeJoin"] },
