  "localCheckpoint": { definition: "A Spark checkpoint stored on executor-local storage. It cuts lineage but is not durable against loss of that storage." },
  "Spark UI": { definition: "Spark's diagnostic interface for jobs, stages, tasks, SQL plans, storage, and execution metrics." },
