  "Isolation": { definition: "Rules controlling how concurrent transactions observe and interfere with one another; the guarantees vary by isolation level." },
  "Durability": { definition: "Once a transaction is committed, its changes survive failures covered by the storage system's guarantees.", aliases: ["durable"] },
