  "Time travel": { definition: "Reading a table at an earlier version or timestamp while the metadata and data files needed for that version remain available." },
  "VACUUM": { definition: "A Delta maintenance operation that deletes eligible unreferenced files after retention rules allow it, limiting access to older table versions.", aliases: ["vacuuming"] },
