  "Logical date": { definition: "The time interval or date a run represents, independent of when the task actually executes.", aliases: ["logical execution date", "logical period", "logical periods"] },
  "Concurrency": { definition: "The number of operations or runs allowed to be in progress at once.", aliases: ["concurrent"] },
