  "Schema registry": { definition: "A service that stores versioned schemas and can enforce configured compatibility checks when schemas are registered.", aliases: ["schema registries", "Confluent Schema Registry"] },
  "Avro": { definition: "A schema-based data serialization format with rules for resolving writer and reader schemas." },
  "Protobuf": { definition: "Protocol Buffers: a schema-based binary serialization system using typed message definitions and numbered fields." },
  "Kafka": { definition: "Apache Kafka: a distributed event log with partitioned topics, durable records, and consumer positions." },
  "Backward compatibility": { definition: "For schema evolution, a new reader schema can read data written with an earlier writer schema; this supports upgrading consumers before producers.", aliases: ["backward-compatible", "backward-only compatibility"] },
  "Forward compatibility": { definition: "For schema evolution, an earlier reader schema can read data written with a new writer schema; this supports upgrading producers before consumers.", aliases: ["forward-compatible"] },
  "Full compatibility": { definition: "Both backward and forward compatibility hold for the versions being checked. Transitive checks extend that comparison to additional historical versions." },
  "Schema drift": { definition: "Changes in data structure over time, including uncoordinated field additions, removals, renames, and type changes." },
