  "Data test": { definition: "An assertion about actual dataset properties, such as key uniqueness, non-null fields, or valid relationships.", aliases: ["data tests", "data assertions", "assertions", "assertion"] },
  "Fixture": { definition: "Controlled test input designed to exercise a particular scenario, including edge cases.", aliases: ["fixtures"] },
  "Great Expectations": { definition: "A framework for expressing, running, and reporting validations of dataset properties." },
  "dbt": { definition: "A transformation tool that manages SQL models, dependencies, tests, and documentation in analytical data platforms." },
  "not_null": { definition: "An assertion that a required field contains no null values." },
  "accepted_values": { definition: "An assertion that values belong to an explicitly allowed set." },
